// violated, the result is a list of violation errors wrapped in
// BGPRuntimeConfigMultiError, or nil if none found.
func (m *BGPRuntimeConfig) ValidateAll() error {
	return m.validate(true)
}

func (m *BGPRuntimeConfig) validate(all bool) error {
	if m == nil {
		return nil
	}

	var errors []error

	// no validation rules for LocalAs

	// no validation rules for RouterId

	// no validation rules for PeerAs

	// no validation rules for PeerIp

	// no validation rules for LocalIp

	// no validation rules for PeerGateway

	// no validation rules for MultihopTtl

	// no validation rules for Password

	// no validation rules for Passive

	// no validation rules for TargetTableId

	// no validation rules for NextHop

	for idx, item := range m.GetAdvertisedPrefixes() {
		_, _ = idx, item

		if all {
			switch v := interface{}(item).(type) {
			case interface{ ValidateAll() error }:
				if err := v.ValidateAll(); err != nil {
					errors = append(errors, BGPRuntimeConfigValidationError{
						field:  fmt.Sprintf("AdvertisedPrefixes[%v]", idx),
						reason: "embedded message failed validation",
						cause:  err,
					})
				}
			case interface{ Validate() error }:
				if err := v.Validate(); err != nil {
					errors = append(errors, BGPRuntimeConfigValidationError{
						field:  fmt.Sprintf("AdvertisedPrefixes[%v]", idx),
						reason: "embedded message failed validation",
						cause:  err,
					})
				}
			}
		} else if v, ok := interface{}(item).(interface{ Validate() error }); ok {
			if err := v.Validate(); err != nil {
				return BGPRuntimeConfigValidationError{
					field:  fmt.Sprintf("AdvertisedPrefixes[%v]", idx),
					reason: "embedded message failed validation",
					cause:  err,
				}
			}
		}

	}

	if len(errors) > 0 {
		return BGPRuntimeConfigMultiError(errors)
	}

	return nil
}

// BGPRuntimeConfigMultiError is an error wrapping multiple validation errors
// returned by BGPRuntimeConfig.ValidateAll() if the designated constraints
// aren't met.
type BGPRuntimeConfigMultiError []error

// Error returns a concatenation of all the error messages it wraps.
func (m BGPRuntimeConfigMultiError) Error() string {
	msgs := make([]string, 0, len(m))
	for _, err := range m {
		msgs = append(msgs, err.Error())
	}
	return strings.Join(msgs, "; ")
}

// AllErrors returns a list of validation violation errors.
func (m BGPRuntimeConfigMultiError) AllErrors() []error { return m }

// BGPRuntimeConfigValidationError is the validation error returned by
// BGPRuntimeConfig.Validate if the designated constraints aren't met.
type BGPRuntimeConfigValidationError struct {
	field  string
	reason string
	cause  error
	key    bool
}

// Field function returns field value.
func (e BGPRuntimeConfigValidationError) Field() string { return e.field }

// Reason function returns reason value.
func (e BGPRuntimeConfigValidationError) Reason() string { return e.reason }

// Cause function returns cause value.
func (e BGPRuntimeConfigValidationError) Cause() error { return e.cause }

// Key function returns key value.
func (e BGPRuntimeConfigValidationError) Key() bool { return e.key }

// ErrorName returns error name.
func (e BGPRuntimeConfigValidationError) ErrorName() string { return "BGPRuntimeConfigValidationError" }

// Error satisfies the builtin error interface
func (e BGPRuntimeConfigValidationError) Error() string {
	cause := ""
	if e.cause != nil {
		cause = fmt.Sprintf(" | caused by: %v", e.cause)
	}

	key := ""
	if e.key {
		key = "key for "
	}

	return fmt.Sprintf(
		"invalid %sBGPRuntimeConfig.%s: %s%s",
		key,
		e.field,
		e.reason,
		cause)
}

var _ error = BGPRuntimeConfigValidationError{}

var _ interface {
	Field() string
	Reason() string
	Key() bool
	Cause() error
	ErrorName() string
} = BGPRuntimeConfigValidationError{}
